// === PARSERS ===
// We need High, Low, and Close for ATR
function getCandles(items) {
    if (!items || items.length === 0) return [];
    // Binance kline format: [time, open, high, low, close, vol...]
    return items
        .filter(i => Array.isArray(i) && i.length > 4)
        .map(i => ({
            high: parseFloat(i[2]),
            low: parseFloat(i[3]),
            close: parseFloat(i[4])
        }));
}

const candles = getCandles(binanceDailyItems);
// We need at least 20 periods + 1 for previous close calculation
if (candles.length < 21) {
    return [{ json: { error: "Insufficient data for volatility analysis" } }];
}

// === TECHNICAL INDICATOR FUNCTIONS ===

// Simple Moving Average
function sma(values, period) {
    if (values.length < period) return 0;
    const slice = values.slice(values.length - period);
    return slice.reduce((a, b) => a + b, 0) / period;
}

// Standard Deviation (for Bollinger Bands)
function stdDev(values, period, average) {
    if (values.length < period) return 0;
    const slice = values.slice(values.length - period);
    const squareDiffs = slice.map(value => Math.pow(value - average, 2));
    const avgSquareDiff = squareDiffs.reduce((a, b) => a + b, 0) / period;
    return Math.sqrt(avgSquareDiff);
}

// Average True Range (for Keltner Channels)
// Uses simple SMA of TR for the channel width (Standard Keltner approach)
function calculateATR(candles, period) {
    if (candles.length < period + 1) return 0;

    let trueRanges = [];
    // Start from index 1 because we need previous close
    // We only need the last 'period' TRs
    const startIndex = candles.length - period;

    for (let i = startIndex; i < candles.length; i++) {
        const current = candles[i];
        const prev = candles[i - 1];

        const hl = current.high - current.low;
        const h_pc = Math.abs(current.high - prev.close);
        const l_pc = Math.abs(current.low - prev.close);

        trueRanges.push(Math.max(hl, h_pc, l_pc));
    }

    return trueRanges.reduce((a, b) => a + b, 0) / period;
}

// === LOGIC CORE ===

const closes = candles.map(c => c.close);
