// 1. Calculate Bollinger Bands (20, 2)
const basis = sma(closes, 20); // Middle Line
const sd = stdDev(closes, 20, basis);
const bbUpper = basis + (2 * sd);
const bbLower = basis - (2 * sd);

// 2. Calculate Keltner Channels (20, 1.5)
// Note: We use the same 'basis' (SMA 20) for the centerline to align them perfectly
const atr = calculateATR(candles, 20);
const kcFactor = 1.5;
const kcUpper = basis + (kcFactor * atr);
const kcLower = basis - (kcFactor * atr);

// 3. Detect Squeeze
// Squeeze is ON when BB are INSIDE Keltner Channels
const squeezeOn = (bbUpper < kcUpper) && (bbLower > kcLower);

// 4. Calculate BB Width (for relative comparison)
const bbw = (basis !== 0) ? (bbUpper - bbLower) / basis : 0;

// 5. Trend Determination (Price vs SMA50)
const ma50 = sma(closes, 50);
const trend = currentPrice > ma50 ? "bullish" : "bearish";

// === OUTPUT ===

let result = {
