        status: squeezeOn ? "Active Squeeze (Low Volatility)" : "Normal Volatility"
    },
    technical_levels: {
        basis_sma20: basis,
        bb_upper: bbUpper,
        bb_lower: bbLower
    }
};

return [{ json: result }];

